css:
.hap13-custom{--md-primary:#2196F3;--md-primary-hover:#1A87E0;--md-navy:#082C5E;--md-ink:#151A21;--md-secondary:#4E535C;--md-tertiary:#767A80;--md-rule:#D6DBE2;--md-card:#EBF0F6;--md-white:#fff;--md-pale:#F5F9FE;--md-radius:8px;color:var(--md-ink);font-family:"PingFang SC","Microsoft YaHei",sans-serif}.hap13-custom *{box-sizing:border-box}.hap13-custom h1,.hap13-custom h2,.hap13-custom h3,.hap13-custom p{margin:0}.hap13-custom [data-custom-lang]{position:absolute;inset:0}.hap13-custom [data-custom-lang="en"]{display:none}html[lang="en"] .hap13-custom [data-custom-lang="zh"]{display:none}html[lang="en"] .hap13-custom [data-custom-lang="en"]{display:block}
.hap13-custom h1,.hap13-custom h2,.hap13-custom h3,.hap13-custom p,.hap13-custom figure{margin:0}
.hap13-custom h1{font-size:56px;line-height:72px;font-weight:600;letter-spacing:-.8px}
.hap13-custom h2{font-size:34px;line-height:48px;font-weight:600}
.hap13-custom h3{font-size:28px;line-height:40px;font-weight:600}
.hap13-custom .ibx-body{font-size:28px;line-height:42px}
.hap13-custom .ibx-small{font-size:22px;line-height:32px}
.hap13-custom .ibx-muted{color:var(--md-secondary)}
.hap13-custom .ibx-quiet{color:var(--md-tertiary)}
.hap13-custom .ibx-eyebrow{position:absolute;left:148px;top:70px;font-size:20px;line-height:28px;color:var(--md-tertiary);letter-spacing:2px}
.hap13-custom .ibx-title{position:absolute;left:148px;top:112px;width:1624px}
.hap13-custom .ibx-sub{position:absolute;left:148px;top:202px;width:1624px;font-size:28px;line-height:40px;color:var(--md-secondary)}
.hap13-custom .ibx-note-label{font-size:20px;color:var(--md-tertiary);line-height:28px}
.hap13-custom .ibx-chip{display:inline-block;padding:4px 13px;background:var(--md-card);border-radius:6px;font-size:21px;line-height:30px;color:var(--md-secondary)}
.hap13-custom .ibx-process-panel{position:absolute;left:148px;top:294px;width:1024px;height:514px;padding:32px 36px;background:var(--md-navy);border-radius:var(--md-radius);color:var(--md-white)}
.hap13-custom .ibx-process-panel .ibx-panel-head{display:flex;align-items:center;justify-content:space-between}
.hap13-custom .ibx-process-panel .ibx-panel-head h2{font-size:30px;line-height:42px}
.hap13-custom .ibx-process-panel .ibx-panel-head span{font-size:20px;color:#C3D4E9}
.hap13-custom .ibx-process-row{position:relative;display:grid;grid-template-columns:repeat(4,1fr);gap:26px;margin-top:32px}
.hap13-custom .ibx-process-step{position:relative;background:var(--md-white);color:var(--md-ink);border-radius:var(--md-radius);padding:20px 18px;height:143px}
.hap13-custom .ibx-process-step:not(:last-child)::after{content:'→';position:absolute;left:calc(100% + 5px);top:49px;color:#B1CBEA;font-size:24px}
.hap13-custom .ibx-process-step .ibx-num{font-size:20px;line-height:28px;color:var(--md-tertiary)}
.hap13-custom .ibx-process-step h3{font-size:27px;line-height:38px;margin-top:10px}
.hap13-custom .ibx-process-step p{font-size:20px;line-height:28px;color:var(--md-secondary);margin-top:2px}
.hap13-custom .ibx-system-band{margin-top:37px;border-top:1px solid #35527A;padding-top:25px;display:flex;gap:12px;align-items:center;flex-wrap:wrap}
.hap13-custom .ibx-system-band strong{font-size:24px;line-height:36px;margin-right:8px}
.hap13-custom .ibx-system-band span{font-size:22px;border:1px solid #6E8BAF;border-radius:6px;padding:7px 16px}
.hap13-custom .ibx-process-caption{font-size:23px;line-height:36px;margin-top:24px!important;color:#D0DEEF}
.hap13-custom .ibx-narrative{position:absolute;left:1220px;top:294px;width:552px}
.hap13-custom .ibx-narrative article{padding-bottom:18px;margin-bottom:18px;border-bottom:1px solid var(--md-rule)}
.hap13-custom .ibx-narrative article:last-child{border:0;margin:0;padding:0}
.hap13-custom .ibx-narrative .ibx-label{font-size:20px;line-height:28px;color:var(--md-tertiary);letter-spacing:1px}
.hap13-custom .ibx-narrative h2{font-size:30px;line-height:42px;margin:7px 0 9px}
.hap13-custom .ibx-narrative p{font-size:25px;line-height:38px;color:var(--md-secondary)}
.hap13-custom .ibx-takeaway{position:absolute;left:148px;top:850px;width:1624px;height:112px;background:var(--md-card);border-radius:var(--md-radius);padding:22px 30px;display:flex;gap:36px;align-items:center}
.hap13-custom .ibx-takeaway b{font-size:28px;color:var(--md-navy);white-space:nowrap}
.hap13-custom .ibx-takeaway p{font-size:26px;line-height:39px;color:var(--md-secondary)}
.hap13-custom .ibx-solution .ibx-title{font-size:52px}
.hap13-custom .ibx-solution .ibx-sub{font-size:27px}
.hap13-custom .ibx-solution-main{position:absolute;left:148px;top:294px;width:1080px;height:522px;border:1px solid var(--md-rule);border-radius:var(--md-radius);padding:30px 34px}
.hap13-custom .ibx-solution-main .ibx-topline{display:flex;align-items:center;justify-content:space-between}
.hap13-custom .ibx-solution-main .ibx-topline h2{font-size:30px}
.hap13-custom .ibx-solution-main .ibx-topline span{font-size:20px;color:var(--md-tertiary)}
.hap13-custom .ibx-solution-flow{display:grid;grid-template-columns:repeat(4,1fr);gap:28px;margin-top:31px}
.hap13-custom .ibx-flow-item{position:relative;background:var(--md-card);border-radius:var(--md-radius);padding:20px 17px;height:152px}
.hap13-custom .ibx-flow-item:not(:last-child)::after{content:'→';position:absolute;left:calc(100% + 6px);top:54px;font-size:24px;color:var(--md-tertiary)}
.hap13-custom .ibx-flow-item .ibx-who{font-size:20px;line-height:28px;color:var(--md-tertiary)}
.hap13-custom .ibx-flow-item h3{font-size:27px;line-height:38px;margin-top:10px}
.hap13-custom .ibx-flow-item p{font-size:21px;line-height:30px;color:var(--md-secondary);margin-top:3px}
.hap13-custom .ibx-flow-item:last-child{background:var(--md-navy);color:var(--md-white)}
.hap13-custom .ibx-flow-item:last-child p,.hap13-custom .ibx-flow-item:last-child .ibx-who{color:#CDDCF0}
.hap13-custom .ibx-exception{border-top:1px solid var(--md-rule);margin-top:30px;padding-top:24px;display:grid;grid-template-columns:154px 1fr;gap:26px;align-items:center}
.hap13-custom .ibx-exception b{font-size:26px;line-height:38px;color:var(--md-navy)}
.hap13-custom .ibx-exception p{font-size:24px;line-height:36px;color:var(--md-secondary)}
.hap13-custom .ibx-objects{font-size:22px;line-height:34px;color:var(--md-tertiary);margin-top:24px!important}
.hap13-custom .ibx-solution-side{position:absolute;left:1276px;top:294px;width:496px;height:522px;background:var(--md-navy);border-radius:var(--md-radius);padding:32px 36px;color:var(--md-white)}
.hap13-custom .ibx-solution-side .ibx-overline{font-size:20px;line-height:30px;color:#B9CEE9;letter-spacing:2px}
.hap13-custom .ibx-solution-side h2{font-size:32px;line-height:46px;margin-top:14px}
.hap13-custom .ibx-solution-side .ibx-intro{font-size:25px;line-height:39px;color:#D8E4F4;margin-top:18px}
.hap13-custom .ibx-solution-side .ibx-feature{font-size:25px;line-height:36px;padding-top:22px;margin-top:22px;border-top:1px solid #456083}
.hap13-custom .ibx-solution-side .ibx-feature span{display:block;font-size:22px;line-height:34px;color:#BCD0EA;margin-top:8px}
.hap13-custom .ibx-solution .ibx-takeaway{padding-top:17px;padding-bottom:17px}
.hap13-custom .ibx-solution .ibx-takeaway p{font-size:25px;line-height:37px}
.hap13-custom .ibx-chip{display:inline-block}.hap13-custom .ibx-solution .ibx-title{font-size:52px}.hap13-custom .ibx-solution .ibx-sub{font-size:27px}
html[lang="en"] .hap13-custom{font-family:"Helvetica Neue",Arial,sans-serif}html[lang="en"] .hap13-custom h1,html[lang="en"] .hap13-custom .ibx-solution .ibx-title{font-size:43px;line-height:60px}html[lang="en"] .hap13-custom .ibx-sub{font-size:25px;line-height:36px}html[lang="en"] .hap13-custom .ibx-process-step h3,html[lang="en"] .hap13-custom .ibx-flow-item h3{font-size:23px;line-height:32px}html[lang="en"] .hap13-custom .ibx-process-step p,html[lang="en"] .hap13-custom .ibx-flow-item p{font-size:18px;line-height:26px}html[lang="en"] .hap13-custom .ibx-narrative h2{font-size:28px;line-height:38px}html[lang="en"] .hap13-custom .ibx-narrative p{font-size:23px;line-height:34px}html[lang="en"] .hap13-custom .ibx-takeaway p{font-size:23px;line-height:34px}html[lang="en"] .hap13-custom .ibx-takeaway b{font-size:24px}html[lang="en"] .hap13-custom .ibx-solution-side h2{font-size:30px;line-height:42px}html[lang="en"] .hap13-custom .ibx-solution-side .ibx-intro{font-size:23px;line-height:34px}html[lang="en"] .hap13-custom .ibx-solution-side .ibx-feature{font-size:24px;line-height:32px}html[lang="en"] .hap13-custom .ibx-solution-side .ibx-feature span{font-size:21px;line-height:30px}html[lang="en"] .hap13-custom .ibx-objects{font-size:20px}
